    @Transactional
    public Person update(String sheetId, String user, long id, long version, String name, String grade,
            LocalDate gradeFrom, Integer terms, LocalDate termsFrom, String contact, String tags) {
        return update(sheetId, user, id, version, name, grade, gradeFrom, terms, termsFrom, contact,
                ClaimService.tagsOf(tags), true);
    }

    private Person update(String sheetId, String user, long id, long version, String name, String grade,
            LocalDate gradeFrom, Integer terms, LocalDate termsFrom, String contact, String tags,
            boolean throughForm) {
        Sheet sheet = sheets.load(sheetId, user);
        LocalDate today = sheet.getToday();
        Person person = people.findByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet"));
        if (person.getVersion() != version) {
            throw changedSince();
        }
        boolean gradeChosen = gradeFrom != null || !grade.equals(person.gradeOn(today));
        if (gradeChosen) {
            SheetService.requireGrade(sheet, grade);
        }
        if (gradeChosen && sheet.isGradeRetired(grade)) {
            throw gradeRetired(grade);
        }
        String trimmed = name.trim();
        if (people.existsBySheetIdAndNameIgnoreCaseAndIdNot(sheetId, trimmed, id)
                || people.findBySheetIdAndAliasIgnoreCase(sheetId, trimmed).isPresent()) {
            throw nameInUse();
        }
        if (throughForm) {
            Set<String> used = usedInTree(sheetId);
            if (used.contains(lower(trimmed)) || person.getAliases().stream().anyMatch(a -> used.contains(lower(a)))) {
                throw nameInUse();
            }
        }
        String reach = contactOf(contact);
        if (reach != null && people.existsBySheetIdAndContactAndIdNot(sheetId, reach, id)) {
            throw contactInUse();
        }
        Rollup.Figures before = rollup.of(sheetId);
        person.setName(trimmed);
        if (gradeChosen) {
            person.setGradeFrom(gradeFrom != null ? gradeFrom : today, grade);
        }
        boolean termsChanged;
        if (termsFrom != null) {
            termsChanged = person.getDatedTerms().stream().noneMatch(
                    t -> t.getFromDate().equals(termsFrom) && Objects.equals(t.getTerms(), terms));
