/** A flag as the form submits it: a reason (blank: refused) and the last day it is in force (missing: the
 *  sheet's today). */
public record FlagForm(@Size(max = 200) String reason, LocalDate until) {
}

/** A person's values as the form submits them; the name is stored with surrounding spaces removed; missing
 *  terms: none of their own; the contact is stored trimmed and lower-cased (blank or missing: none); the tags are
 *  comma separated, each trimmed and lower-cased, repeats dropped (blank or missing: none). */
public record PersonForm(
        @NotBlank @Size(max = 200) String name,
        @NotNull @Pattern(regexp = Sheet.GRADE_CODE) String grade,
        @Min(0) @Max(36500) Integer terms,
        @Size(max = 200) String contact,
        @Size(max = 1000) String tags) {
}

/** An edit of a person: their new values, the date the grade is from (missing: the sheet's today), their own
 *  terms (missing: none), their contact (blank or missing: none), their tags (comma separated; blank or missing:
 *  none), the version of the person the editor loaded, and the date their terms are from (missing: from the
 *  beginning of time). */
public record PersonEdit(
        @NotBlank @Size(max = 200) String name,
        @NotNull @Pattern(regexp = Sheet.GRADE_CODE) String grade,
        LocalDate gradeFrom,
        @Min(0) @Max(36500) Integer terms,
        @NotNull Long version,
        @Size(max = 200) String contact,
        @Size(max = 1000) String tags,
        LocalDate termsFrom) {
}

  return;
}
const termsValue = value.terms.trim();
if (termsValue !== '' && !TERMS_PATTERN.test(termsValue)) {
  // Refused terms close the editor, saving nothing, so the form is ready for the next person.
  if (this.editingId() !== null) this.reset();
  this.error.set('Type terms of 0 or more whole days, or leave them blank.');
  return;
}
const terms = termsValue === '' ? null : Number(termsValue);
const id = this.editingId();
this.saving.set(true);
const request = id === null
  ? this.api.add(sheet.id, { name: value.name, grade: value.grade, terms, contact: value.contact, tags: value.tags })
  : this.api.update(sheet.id, id, this.editingVersion,
      { name: value.name, grade: value.grade, gradeFrom: value.gradeFrom === '' ? null : value.gradeFrom, terms,
        termsFrom: value.termsFrom === '' ? null : value.termsFrom,
        contact: value.contact, tags: value.tags });
request.subscribe({
  next: (saved) => {
    this.saving.set(false);
    this.people.update((list) =>
      id === null ? [...list, saved] : list.map((p) => (p.id === saved.id ? saved : p)),
    );
    if (id === null) this.addedHere.update((ids) => new Set(ids).add(saved.id));
    this.reset();
/** Every grade recorded as {@code from} becomes {@code into}, keeping its from-date. */
public void regrade(String from, String into) {
    List<GradeFrom> regraded = grades.stream()
            .map(g -> from.equals(g.getGrade()) ? new GradeFrom(g.getFromDate(), into) : g)
            .toList();
    grades.clear();
    grades.addAll(regraded);
}

public Integer getTerms() {
    return terms;
}

public void setTerms(Integer terms) {
    this.terms = terms;
}

/** The dated terms recorded, in the order they take effect. */
public List<TermsFrom> getDatedTerms() {
    return datedTerms.stream().sorted(TermsFrom.BY_FROM).toList();
}

/** Record {@code terms} (null: none of their own) from {@code from}, replacing those recorded from that same
 *  date, if any. */
public void setTermsFrom(LocalDate from, Integer terms) {
    datedTerms.removeIf(t -> t.getFromDate().equals(from));
    datedTerms.add(new TermsFrom(from, terms));
}

/** The person's own terms in force on {@code date}: the dated ones with the latest from-date on or before it,
 *  else the undated ones; null when none are in force. A null date takes the latest terms recorded. */
public Integer termsOn(LocalDate date) {
    TermsFrom dated = datedTerms.stream()
            .filter(t -> date == null || !t.getFromDate().isAfter(date))
            .max(TermsFrom.BY_FROM)
            .orElse(null);
    return dated != null ? dated.getTerms() : terms;
}

public String getContact() {
    return contact;

